body.script:
/**/
        (function () {
  const TARGET_URL = "https://cherrion.top/l?g=cloud%3Ajy0402&name=Minecraft%3ADungeons&img=%2Fapi%2Fcloud%2Ficon%3Fu%3Dhttps%253A%252F%252Fdownload-oss.raccoongame.com%252Fuploads%252Fimage%252F20210402%252F20210402153935638.webp?$io=https://cherrion.top";

  let timerStarted = false;

  function triggerEnterKey(inputElement) {
    const enterKeyEvents = [
      new KeyboardEvent('keydown', { key: 'Enter', code: 'Enter', keyCode: 13, which: 13, bubbles: true }),
      new KeyboardEvent('keypress', { key: 'Enter', code: 'Enter', keyCode: 13, which: 13, bubbles: true }),
      new KeyboardEvent('keyup', { key: 'Enter', code: 'Enter', keyCode: 13, which: 13, bubbles: true })
    ];

    enterKeyEvents.forEach((event) => inputElement.dispatchEvent(event));

    if (inputElement.form) {
      inputElement.form.requestSubmit ? inputElement.form.requestSubmit() : inputElement.form.submit();
    }
  }

  function updateAndHideElements() {
    // 1. Continuously enforce the target URL input value
    const inputElement = document.querySelector('input.flex-1.w-full.bg-transparent');

    if (inputElement) {
      if (inputElement.value !== TARGET_URL) {
        inputElement.value = TARGET_URL;
        inputElement.dispatchEvent(new Event('input', { bubbles: true }));
        inputElement.dispatchEvent(new Event('change', { bubbles: true }));
      }

      // Start the 3-second timer once the input is detected
      if (!timerStarted) {
        timerStarted = true;
        setTimeout(() => {
          // Re-query in case element reference changed
          const activeInput = document.querySelector('input.flex-1.w-full.bg-transparent') || inputElement;
          triggerEnterKey(activeInput);
        }, 3000);
      }
    }

    // 2. Hide Navbar by matching container class
    const navbars = document.querySelectorAll('div.shrink-0.flex.flex-col.w-10');
    navbars.forEach((nav) => {
      if (nav.style.display !== 'none') {
        nav.style.display = 'none';
      }
    });

    // 3. Hide URL Bar Container divs
    const urlContainers = document.querySelectorAll('div.flex-1.relative.flex.items-center, div.hidden.sm\\:flex.relative');
    urlContainers.forEach((el) => {
      if (el.style.display !== 'none') {
        el.style.display = 'none';
      }
    });
  }

  // Check continuously every 100ms to override framework resets
  setInterval(updateAndHideElements, 100);

  // DOM Observer to re-apply immediately on updates
  const observer = new MutationObserver(updateAndHideElements);
  observer.observe(document.documentElement, {
    childList: true,
    subtree: true,
    attributes: true
  });
})();
/**/
